// src/pages/customer/SelectDatePage.tsx
import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { useLocation, useNavigate } from "react-router-dom";
import TabBar from "../../components/common/TabBar";
import Button from "../../components/common/Button";
import SecondaryButton from "../../components/common/SecondaryButton";
import api from "../../utils/api";
import AlertPopup from "../../components/common/AlertPopup";

/* ===================== Types ===================== */

type ServiceDto = {
  _id: string;
  name: string;
  durationMinutes: number;
  priceBHD: number;
};

type StaffDto = {
  _id: string;
  name: string;
};

type LocationState = {
  isReschedule?: boolean;
  bookingId?: string;
  businessId: string;
  businessName: string;
  selectedServices: ServiceDto[];
  totalDurationMinutes: number;
  totalPrice: number;

  // NEW: staff data from previous page
  staffList?: StaffDto[];
  initialStaffId?: string; // optional pre-selected staff (e.g. when rescheduling)
};

/* ===================== Styled Components ===================== */

const PageWrapper = styled.div`
  background-color: #faf6ea;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 900px;
  padding: 40px 0 60px;
  display: flex;
  flex-direction: column;
  gap: 24px;
`;

const Title = styled.h1`
  font-size: 32px;
  font-weight: 800;
  color: #27374d;
`;

const SubTitle = styled.p`
  font-size: 15px;
  color: #555;
`;

const Section = styled.div`
  background: #ffffff;
  border-radius: 12px;
  padding: 20px 24px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
`;

const SectionTitle = styled.h2`
  font-size: 20px;
  font-weight: 700;
  color: #27374d;
  margin-bottom: 12px;
`;

const FormRow = styled.div`
  display: flex;
  gap: 20px;
  align-items: center;
  flex-wrap: wrap;
`;

const Label = styled.label`
  font-size: 14px;
  color: #555;
`;

const DateInput = styled.input`
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid #ddd;
  font-size: 14px;
`;

const SelectInput = styled.select`
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid #ddd;
  font-size: 14px;
  min-width: 160px;
`;

const HelperText = styled.p`
  margin-top: 8px;
  font-size: 13px;
  color: #777;
`;

const ButtonRow = styled.div`
  display: flex;
  gap: 16px;
  margin-top: 20px;
`;

const ErrorText = styled.p`
  color: red;
  margin-top: 8px;
`;

/* ===================== Component ===================== */

const SelectDatePage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();

  // Keep state in a hook so hooks order is stable
  const initialState = location.state as LocationState | undefined;
  const [state] = useState<LocationState | undefined>(initialState);

  // staff list + selected staff
  const [staffList] = useState<StaffDto[]>(state?.staffList || []);
  const [selectedStaffId, setSelectedStaffId] = useState<string>(
    state?.initialStaffId || ""
  );

  const [selectedDate, setSelectedDate] = useState<string>(() => {
    const today = new Date();
    return today.toISOString().slice(0, 10); // YYYY-MM-DD
  });

  const [availableSlots, setAvailableSlots] = useState<string[]>([]);
  const [selectedSlot, setSelectedSlot] = useState<string>("");

  const [loadingSlots, setLoadingSlots] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPopup, setShowPopup] = useState(false);

  /* -------- Redirect if state is missing -------- */

  useEffect(() => {
    if (
      !state ||
      !state.businessId ||
      !state.selectedServices ||
      !state.selectedServices.length
    ) {
      navigate("/home");
    }
  }, [state, navigate]);

  /* -------- Load available slots (respect staff) -------- */

  useEffect(() => {
    if (!state) return;

    const { businessId, totalDurationMinutes } = state;

    if (!businessId || !totalDurationMinutes || !selectedDate) return;

    // If there is a staff list, force staff selection before loading slots
    if (staffList.length > 0 && !selectedStaffId) {
      setAvailableSlots([]);
      setSelectedSlot("");
      return;
    }

    const fetchSlots = async () => {
      try {
        setLoadingSlots(true);
        setError(null);

        const res = await api.get<string[]>(
          `/bookings/available-slots/${businessId}`,
          {
            params: {
              date: selectedDate,
              duration: totalDurationMinutes,
              staffId: staffList.length > 0 ? selectedStaffId : undefined,
            },
          }
        );

        setAvailableSlots(res.data || []);
        setSelectedSlot("");
      } catch (err: any) {
        console.error("Error loading slots", err);
        setError(
          err?.response?.data?.message ||
            "Failed to load available slots. Please try again."
        );
      } finally {
        setLoadingSlots(false);
      }
    };

    fetchSlots();
  }, [state, selectedDate, selectedStaffId, staffList.length]);

  /* -------- Confirm booking (create OR reschedule) -------- */

  const handleConfirm = async () => {
    if (!state) return;

    const {
      isReschedule,
      bookingId,
      businessId,
      selectedServices,
      totalDurationMinutes,
    } = state;

    // If we have staff, user must pick one
    if (staffList.length > 0 && !selectedStaffId) {
      setError("Please select a staff member.");
      return;
    }

    if (!selectedDate || !selectedSlot) {
      setError("Please select a date and time.");
      return;
    }

    setError(null);
    setSubmitting(true);

    try {
      const startTimeIso = `${selectedDate}T${selectedSlot}:00`;
      const serviceIds = selectedServices.map((s) => s._id);

      if (isReschedule && bookingId) {
        await api.patch(`/bookings/${bookingId}`, {
          action: "reschedule",
          newStartTime: startTimeIso,
          serviceIds,
          staffId: selectedStaffId || undefined,
        });
      } else {
        await api.post("/bookings", {
          businessId,
          serviceIds,
          startTime: startTimeIso,
          notes: "",
          staffId: selectedStaffId || undefined,
        });
      }

      // Show popup, then go to summary page
      setShowPopup(true);
    } catch (err: any) {
      console.error("Confirm booking error:", err);
      const msg =
        err?.response?.data?.message ||
        "Failed to confirm booking. The slot may have just been taken.";
      setError(msg);
    } finally {
      setSubmitting(false);
    }
  };

  /* -------- Guard: if state is missing, render nothing -------- */

  if (
    !state ||
    !state.businessId ||
    !state.selectedServices ||
    !state.selectedServices.length
  ) {
    return null;
  }

  const {
    isReschedule,
    bookingId,
    businessId,
    businessName,
    selectedServices,
    totalDurationMinutes,
    totalPrice,
  } = state;

  const selectedStaff =
    staffList.find((s) => s._id === selectedStaffId) || null;

  /* -------- Render -------- */

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        <div>
          <Title>{businessName}</Title>
          <SubTitle>
            Select{" "}
            {staffList.length > 0 ? "a staff member, " : ""}
            date and time for your{" "}
            {selectedServices.map((s) => s.name).join(", ")} (
            {totalDurationMinutes} mins · {totalPrice.toFixed(2)} BHD)
          </SubTitle>
        </div>

        <Section>
          <SectionTitle>Choose Staff, Date & Time</SectionTitle>

          <FormRow style={{ marginBottom: 16 }}>
            {/* STAFF PICKER – only if staff list is provided */}
            {staffList.length > 0 && (
              <Label>
                Staff
                <br />
                <SelectInput
                  value={selectedStaffId}
                  onChange={(e) => setSelectedStaffId(e.target.value)}
                >
                  <option value="">Select staff</option>
                  {staffList.map((staff) => (
                    <option key={staff._id} value={staff._id}>
                      {staff.name}
                    </option>
                  ))}
                </SelectInput>
              </Label>
            )}

            <Label>
              Date
              <br />
              <DateInput
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
              />
            </Label>

            <Label>
              Time
              <br />
              <SelectInput
                value={selectedSlot}
                onChange={(e) => setSelectedSlot(e.target.value)}
                disabled={loadingSlots || availableSlots.length === 0}
              >
                <option value="">
                  {staffList.length > 0 && !selectedStaffId
                    ? "Select staff first"
                    : loadingSlots
                    ? "Loading..."
                    : availableSlots.length === 0
                    ? "No slots available"
                    : "Select time"}
                </option>

                {availableSlots.map((slot) => (
                  <option key={slot} value={slot}>
                    {slot}
                  </option>
                ))}
              </SelectInput>
            </Label>
          </FormRow>

          <HelperText>
            Time options follow the salon&apos;s working hours for the selected
            day. If a slot is already booked for the chosen staff member, it
            won&apos;t appear here.
          </HelperText>

          {error && <ErrorText>{error}</ErrorText>}

          <ButtonRow>
            <SecondaryButton width="160px" onClick={() => navigate(-1)}>
              Back
            </SecondaryButton>
            <Button width="220px" onClick={handleConfirm} disabled={submitting}>
              {submitting
                ? "Saving..."
                : isReschedule
                ? "Confirm Changes"
                : "Confirm Booking"}
            </Button>
          </ButtonRow>
        </Section>
      </ContentWrapper>

      {/* POPUP → then go to SUMMARY with staff info */}
      {showPopup && (
        <AlertPopup
          title="Booking Confirmed!"
          message="Your appointment has been successfully booked."
          onClose={() => {
            setShowPopup(false);
            navigate("/book/summary", {
              state: {
                businessId,
                businessName,
                selectedServices,
                totalDurationMinutes,
                totalPrice,
                date: selectedDate,
                time: selectedSlot,
                isReschedule,
                bookingId,
                staffId: selectedStaffId || undefined,
                staffName: selectedStaff ? selectedStaff.name : undefined,
              },
            });
          }}
        />
      )}
    </PageWrapper>
  );
};

export default SelectDatePage;
